<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireLogin();
$stmt = $pdo->prepare("SELECT * FROM invoices WHERE tenant_id = :tenant_id AND status IN ('unpaid','overdue') ORDER BY due_date"); $stmt->execute([':tenant_id'=>currentUser()['id']]); $invoices = $stmt->fetchAll(); pageHeader('Pay Bills'); ?>
<div class="mb-8"><h1 class="text-3xl font-bold">Pay your bill</h1><p class="mt-2 text-slate-600">Choose hosted GCash checkout or submit a manual GCash receipt.</p></div><div class="space-y-5"><?php foreach ($invoices as $invoice): ?><div class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><div class="flex flex-wrap items-center justify-between gap-4"><div><h2 class="text-xl font-semibold"><?= e($invoice['month_year']) ?></h2><p class="text-slate-600">Due <?= e($invoice['due_date']) ?> · <?= money($invoice['total_amount']) ?></p></div><button class="gcash-button rounded bg-teal-700 px-4 py-2 font-semibold text-white" data-invoice-id="<?= e((string)$invoice['id']) ?>" type="button">Pay with GCash</button></div><form class="mt-5 flex flex-wrap items-end gap-3 border-t border-slate-100 pt-5" method="post" action="../api/submit_manual_payment.php" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="invoice_id" value="<?= e((string)$invoice['id']) ?>"><label class="text-sm font-semibold">Reference number<input class="mt-1 block rounded border border-slate-300 p-2" name="reference_number" required maxlength="120"></label><label class="text-sm font-semibold">Receipt image<input class="mt-1 block rounded border border-slate-300 p-2" type="file" name="receipt" accept="image/png,image/jpeg" required></label><button class="rounded border border-slate-300 px-4 py-2 font-semibold" type="submit">Submit manual payment</button></form></div><?php endforeach; ?><?php if (!$invoices): ?><div class="rounded-lg border border-emerald-200 bg-emerald-50 p-5 text-emerald-900">There are no unpaid invoices.</div><?php endif; ?></div><script>document.querySelectorAll('.gcash-button').forEach(function (button) { button.addEventListener('click', async function () { button.disabled = true; const response = await fetch('../api/create_gcash_session.php', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({invoice_id:button.dataset.invoiceId, csrf_token:'<?= e(csrfToken()) ?>'})}); const data = await response.json(); if (data.checkout_url) window.location.href = data.checkout_url; else { alert(data.error || 'Unable to start checkout.'); button.disabled = false; } }); });</script><?php pageFooter(); ?>